/* 5학년 1학기 음악 2. 감상 — 음악 요소를 감지하고 구별하기(1~10차시), 다양한 문화권 음악의 특징과 구성 인식하기(11~20차시),
 * 음악의 배경과 활용 설명하기(21~29차시).
 * 화면 건반으로 들려주는 가락은 이 단원을 위해 새로 지었거나, 저작권이 끝난 곡의 첫머리 몇 음만 옮긴 것이다:
 *   '작은 별' 주제(프랑스 민요, 모차르트 변주곡 K.265의 주제), 그리그 「페르 귄트」 중 '산속 마왕의 궁전에서'(1875, 라단조로 옮김),
 *   하이든 교향곡 94번 '놀람' 2악장 주제(1791), 베토벤 교향곡 9번 4악장 '환희의 송가'(1824), 브람스 '자장가'(1868), '나비야'(독일 민요).
 * 감상 곡(교사가 음원으로 들려줌)은 모두 작곡가 사후 70년이 지났거나 전통 음악이다: 생상스 「동물의 사육제」, 라벨 「볼레로」(1928, 라벨 1937년 사망),
 * 비발디 「사계」, 멘델스존 '결혼 행진곡', 종묘제례악·대취타·강강술래·아리랑(전통). 노랫말은 싣지 않는다.
 * 플라멩코 12박(3·6·8·10·12박 강세), 가믈란의 큰 공 주기, 메기고 받는 노래는 널리 알려진 전통 형식이다.
 */
